import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const URL = process.env.TEST_URL || 'http://127.0.0.1:4174/';
const KEY = 'stillwater-cultivator-v1';
let failures = 0;
const check = (label, ok, detail = '') => {
  console.log(`${ok ? 'PASS' : 'FAIL'} · ${label}${detail ? ` · ${detail}` : ''}`);
  if (!ok) failures++;
};
const cost = (base, realm, stage) => Math.round(base * Math.pow(1.06, realm * 10 + stage) * Math.pow(1.14, realm));
const majorCost = (base, realm) => Math.round(base * Math.pow(1.06, realm * 10) * Math.pow(1.14, realm) * 3);
const spiritMinor = (realm, stage) => cost(120, realm, stage);
const bodyMinor = (realm, stage) => cost(90, realm, stage);
const spiritMajor = (realm) => majorCost(120, realm + 1);
const bodyMajor = (realm) => majorCost(90, realm + 1);
const base = (over = {}) => ({
  version: 5, qi: 10000, stones: 100,
  spirit: { realm: 0, stage: 0, breaks: 0, criticals: 0, failures: 0, breakXp: 0, cooldownUntil: 0, bonuses: { qi: 0, spell: 0, dao: 0 } },
  body: { realm: 0, stage: 0, unlocked: false, breaks: 0, criticals: 0, failures: 0, breakXp: 0, cooldownUntil: 0, bonuses: { hp: 0, attack: 0, guard: 0 } },
  ...over,
});

const browser = await chromium.launch({ headless: true });
async function open(save) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  page.on('pageerror', e => { console.log('PAGE ERROR ·', e.message); failures++; });
  await page.addInitScript(([k, v]) => localStorage.setItem(k, v), [KEY, JSON.stringify(save)]);
  await page.goto(URL, { waitUntil: 'load' });
  await page.waitForTimeout(300);
  return { page, context };
}
const saved = page => page.evaluate(k => JSON.parse(localStorage.getItem(k)), KEY);
const setRandom = (page, values) => page.evaluate(v => { window.__rolls = v; Math.random = () => window.__rolls.length ? window.__rolls.shift() : 0.99; }, values);
const cardText = page => page.locator('#dualCultivation').textContent();

// 1. Minor success
{
  const c0 = spiritMinor(1, 0);
  const { page, context } = await open(base({ qi: 1000, spirit: { ...base().spirit, realm: 1, stage: 0, breakXp: 4 } }));
  check('minor card shows success chance', (await cardText(page)).includes('% success'));
  await page.locator('[data-action="open-spirit-break"]').click();
  await page.waitForTimeout(100);
  check('minor modal shows cost and chance', (await page.locator('#modalText').textContent()).includes('Success chance') && (await page.locator('#modalText').textContent()).includes('20% of the qi cost'));
  await setRandom(page, [0.01, 0.99]);
  await page.locator('[data-action="attempt-spirit-break"]').click();
  await page.waitForTimeout(200);
  const s = await saved(page);
  check('minor success advances one stage', s.spirit.realm === 1 && s.spirit.stage === 1);
  check('minor success consumes full cost', s.qi === 1000 - c0, `qi ${s.qi}, expected ${1000 - c0}`);
  check('minor success resets breakthrough insight', s.spirit.breakXp === 0);
  check('minor success clears cooldown', s.spirit.cooldownUntil === 0);
  check('minor success shows animation', await page.locator('.tribulation').count() > 0);
  await context.close();
}

// 2. Minor failure
{
  const c0 = spiritMinor(1, 0);
  const { page, context } = await open(base({ qi: 1000, spirit: { ...base().spirit, realm: 1, stage: 0 } }));
  await page.locator('[data-action="open-spirit-break"]').click();
  await setRandom(page, [0.99]);
  await page.locator('[data-action="attempt-spirit-break"]').click();
  await page.waitForTimeout(250);
  const s = await saved(page);
  check('minor failure keeps realm and stage', s.spirit.realm === 1 && s.spirit.stage === 0);
  check('minor failure consumes 20% of cost', s.qi === 1000 - Math.round(c0 * .2), `qi ${s.qi}, expected ${1000 - Math.round(c0 * .2)}`);
  check('minor failure grants one insight', s.spirit.breakXp === 1);
  check('minor failure sets ~20s cooldown', s.spirit.cooldownUntil - Date.now() > 18000 && s.spirit.cooldownUntil - Date.now() <= 20000, `${s.spirit.cooldownUntil - Date.now()}ms`);
  check('failure animation shown', await page.locator('.tribulation.fail').count() > 0);
  check('cooldown disables card button', await page.locator('[data-action="open-spirit-break"]').isDisabled());
  check('cooldown visible in card', (await cardText(page)).includes('recovering') || (await cardText(page)).includes('RECOVERING'));
  check('insight visible in card', (await cardText(page)).includes('insight +5%'));
  await context.close();
}

// 3. Chance rises with insight
{
  const mk = xp => base({ qi: 1000, spirit: { ...base().spirit, realm: 1, stage: 0, breakXp: xp } });
  const a = await open(mk(0)); const b = await open(mk(1));
  const readChance = async page => {
    const text = await page.locator('#characterPanel').textContent();
    const m = text.match(/SPIRIT BREAK(\d+)%/);
    return m ? Number(m[1]) : null;
  };
  const c1 = await readChance(a.page), c2 = await readChance(b.page);
  check('breakthrough insight raises next chance by 5%', c1 !== null && c2 === c1 + 5, `${c1}% → ${c2}%`);
  await a.context.close(); await b.context.close();
}

// 4. Major success (critical)
{
  const c0 = spiritMajor(4);
  const { page, context } = await open(base({ qi: 1e9, spirit: { ...base().spirit, realm: 4, stage: 9, breakXp: 6 } }));
  await page.locator('[data-action="open-spirit-break"]').click();
  await page.waitForTimeout(100);
  check('major modal labels the major breakthrough', (await page.locator('#modalEyebrow').textContent()).includes('MAJOR BREAKTHROUGH'));
  await setRandom(page, [0.01, 0.01]);
  await page.locator('[data-action="attempt-spirit-break"]').click();
  await page.waitForTimeout(250);
  const s = await saved(page);
  check('major success advances realm and resets stage', s.spirit.realm === 5 && s.spirit.stage === 0);
  check('major success consumes full major cost', s.qi === 1e9 - c0, `qi delta ${1e9 - s.qi}, expected ${c0}`);
  check('major success resets insight', s.spirit.breakXp === 0);
  check('major critical doubles attributes', s.spirit.bonuses.qi === 2 && s.spirit.criticals === 1);
  check('major success shows modal', await page.locator('#modalBackdrop').isVisible());
  await context.close();
}

// 5. Major failure
{
  const c0 = spiritMajor(4);
  const { page, context } = await open(base({ qi: 1e9, spirit: { ...base().spirit, realm: 4, stage: 9, breakXp: 0 } }));
  await page.locator('[data-action="open-spirit-break"]').click();
  await setRandom(page, [0.99]);
  await page.locator('[data-action="attempt-spirit-break"]').click();
  await page.waitForTimeout(250);
  const s = await saved(page);
  check('major failure keeps stage X', s.spirit.realm === 4 && s.spirit.stage === 9);
  check('major failure consumes 20% of major cost', s.qi === 1e9 - Math.round(c0 * .2), `qi delta ${1e9 - s.qi}, expected ${Math.round(c0 * .2)}`);
  check('major failure grants two insight', s.spirit.breakXp === 2);
  check('major failure sets ~60s cooldown', s.spirit.cooldownUntil - Date.now() > 58000 && s.spirit.cooldownUntil - Date.now() <= 60000);
  await context.close();
}

// 6. Body minor + body major use body costs
{
  const c0 = bodyMinor(0, 0);
  const { page, context } = await open(base({ qi: 1000, spirit: { ...base().spirit, realm: 3, stage: 0 }, body: { ...base().body, unlocked: true, realm: 0, stage: 0 } }));
  await page.locator('[data-action="open-body-break"]').click();
  await setRandom(page, [0.01, 0.99]);
  await page.locator('[data-action="attempt-body-break"]').click();
  await page.waitForTimeout(200);
  const s = await saved(page);
  check('body minor success advances body stage', s.body.stage === 1 && s.spirit.stage === 0);
  check('body minor spends body cost', s.qi === 1000 - c0, `qi ${s.qi}, expected ${1000 - c0}`);
  check('body minor grants body attributes', s.body.bonuses.hp === 0.5 && s.body.bonuses.attack === 0.5);
  check('body success animation shown', await page.locator('.body-trial').count() > 0);
  await context.close();
}

// 7. Chance hard cap
{
  const { page, context } = await open(base({ qi: 1e9, spirit: { ...base().spirit, realm: 14, stage: 9, breakXp: 500 } }));
  const text = await page.locator('#characterPanel').textContent();
  const m = text.match(/SPIRIT BREAK(\d+)%/);
  check('success chance caps at 95%', m && Number(m[1]) === 95, m ? `${m[1]}%` : 'not found');
  await context.close();
}

// 8. v4 migration adds breakthrough fields without shifting realm
{
  const old = base({ version: 4, qi: 100, spirit: { realm: 3, stage: 4, breaks: 1, criticals: 0, failures: 0, bonuses: { qi: 1, spell: 1, dao: 1 } } });
  delete old.spirit.breakXp; delete old.spirit.cooldownUntil;
  const { page, context } = await open(old);
  const s = await saved(page);
  check('v4 save keeps spirit realm', s.spirit.realm === 3 && s.spirit.stage === 4);
  check('v4 save gains insight fields', s.spirit.breakXp === 0 && s.spirit.cooldownUntil === 0);
  check('save version is 5', s.version === 5);
  await context.close();
}

await browser.close();
console.log(`\n${failures === 0 ? 'ALL CHECKS PASSED' : `${failures} CHECK(S) FAILED`}`);
process.exit(failures === 0 ? 0 : 1);

