{
  const c0 = spiritMinor(0, 0);
  const { page, context } = await open(base({ qi: 200, spirit: { ...base().spirit, realm: 0, stage: 0 } }));
  await page.locator('[data-action="open-spirit-break"]').click();
  await page.waitForTimeout(100);
  const modal = await page.locator('#modalText').textContent();
  check('Mortal awakening opens a minor breakthrough modal', modal.includes('MINOR BREAKTHROUGH') && modal.includes('Qi Condensation I'));
