  const s = await saved(page);
  check('Mortal awakening enters Qi Condensation I', s.spirit.realm === 1 && s.spirit.stage === 0);
  check('Mortal awakening consumes the awakening cost', s.qi === 200 - c0, `qi ${s.qi}, expected ${200 - c0}`);
  await context.close();
}

// 13. Chance hard floor
{
  const { page, context } = await open(base({ qi: 1e9, toxicity: 100, toxicityAt: Date.now() + 3600000, spirit: { ...base().spirit, realm: 14, stage: 9 } }));
  const c = await charChance(page);
  check('success chance floors at 10%', c === 10, `${c}%`);
  await context.close();
}

