.cult-status-row{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-top:12px;padding:12px 15px;border:1px solid #e7d9c8;background:#fbf5ea;border-radius:8px}
.cult-status-row>span{display:flex;flex-direction:column;gap:2px;font-size:9px;color:#7d6a52;flex:1;min-width:160px}
.cult-status-row b{font-size:10px;letter-spacing:.6px;color:#8a5a3a}
.cult-status-row small{font-size:8px;color:#9b8a70}
.cult-status-row .hazard-deviation b{color:#8a4f56}
.cult-status-row .action-btn{margin-left:auto}
.cult-hazards{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}
.cult-hazards span{font-size:8px;letter-spacing:.4px;padding:3px 7px;border-radius:999px;background:#f7eee1;border:1px solid #ead9c2;color:#8a5a3a;font-weight:700}
.cult-hazards .hazard-deviation{background:#f7e9ec;border-color:#e7cdd3;color:#8a4f56}

.cult-hazards .hazard-deviation{background:#f7e9ec;border-color:#e7cdd3;color:#8a4f56}
.modal{box-sizing:border-box}
@media(max-width:560px){.modal{padding:26px 18px}.break-mods{grid-template-columns:1fr;max-width:none}.modal-actions{flex-wrap:wrap}.modal-actions button{flex:1 1 100%;min-width:0}.cult-status-row>span{min-width:0}}
.small-note{margin-top:9px;font-size:8px;line-height:1.55;color:#90988d}
.action-btn.gold{background:#fbf3dc;border-color:#e5d6ac;color:#8f7440}
